// 只有以下固定字段/有限tag合法；JSON与binary共用本遍历，调用者不能选择删字段子集。
#pragma once
#include "work_execution.hpp"
#include "exact_struct_codec.hpp"
namespace hanmo::resident::work_fields {
using namespace exact_fields;
// 原Actor分支只写原三字段；专业owner直接复用，不创建临时联合或额外tag。
template<class C> Status actor_action_binding(C& c,ActorActionWorkBinding& x){required_ref(c,"action_id",x.action_id);required_ref(c,"action_kind",x.action_kind);c.object("source_owner_ref",[&](auto& z){return source(z,x.source_owner_ref);});return c.status();}
template<class C> Status binding(C& c,WorkExecutionBinding& v){Integer tag=v.index();finite(c,"tag",tag,1);if(!c.status().ok)return c.status();if(c.reading()){if(tag==0){if(!prepare_checkpoint_default_values<ActorActionWorkBinding>(c).ok)return c.status();v=ActorActionWorkBinding{};}else{if(!prepare_checkpoint_default_values<OwnerPeriodWorkBinding>(c).ok)return c.status();v=OwnerPeriodWorkBinding{};}}if(tag==0){auto& x=std::get<ActorActionWorkBinding>(v);actor_action_binding(c,x);}else{auto& x=std::get<OwnerPeriodWorkBinding>(v);Integer domain=static_cast<Integer>(x.domain);finite(c,"domain",domain,2);if(c.status().ok&&c.reading())x.domain=static_cast<WorkPeriodOwner>(domain);required_ref(c,"activity_kind",x.activity_kind);required_ref(c,"activity_id",x.activity_id);required_ref(c,"registered_period_profile",x.registered_period_profile);}if(c.status().ok)take(validate_work_binding(v));return c.status();}
template<class C> Status period(C& c,WorkPeriodRef& v){c.object("binding",[&](auto& x){return binding(x,v.binding);});c.field("period_ordinal",v.period_ordinal);c.field("from_tick",v.from_tick);c.field("to_tick",v.to_tick);c.field("source_schema_version",v.source_schema_version);if(c.status().ok&&(v.period_ordinal<0||v.from_tick<0||v.to_tick<=v.from_tick||v.source_schema_version!=1))return c.reject("InvalidWorkPeriodRef");return c.status();}
template<class C> Status state(C& c,WorkExecutionState& v){required_ref(c,"work_unit_id",v.work_unit_id);c.field("total_work_units",v.total_work_units);c.field("completed_work_units",v.completed_work_units);c.optional("last_processed_period",v.last_processed_period,[](auto& x,auto& p){return period(x,p);});Integer phase=static_cast<Integer>(v.phase);finite(c,"phase",phase,5);if(c.status().ok&&c.reading())v.phase=static_cast<WorkExecutionPhase>(phase);required_ref(c,"running_policy_ref",v.running_policy_ref);if(c.status().ok)take(validate_work_execution_state(v));return c.status();}
template<class C> Status source_list(C& c,const char* key,std::vector<SourceRef>& v){return c.sequence(key,v,[](auto& x,auto& ref){return source(x,ref);});}
template<class C> Status view(C& c,WorkPeriodView& v){c.object("ref",[&](auto& x){return period(x,v.ref);});c.sequence("actual_actor_roles",v.actual_actor_roles,[](auto& x,auto& role){required_ref(x,"actor_id",role.actor_id);return required_ref(x,"role",role.role);});references(c,"actual_labor_allocations",v.actual_labor_allocations);references(c,"facility_claim_refs",v.facility_claim_refs);required_ref(c,"work_unit_id",v.work_unit_id);c.field("units_before",v.units_before);c.field("units_added",v.units_added);c.field("units_after",v.units_after);source_list(c,"resource_effect_refs",v.resource_effect_refs);source_list(c,"exertion_source_refs",v.exertion_source_refs);Integer d=static_cast<Integer>(v.disposition);finite(c,"disposition",d,2);if(c.status().ok&&c.reading())v.disposition=static_cast<WorkPeriodDisposition>(d);c.optional("reason",v.reason,[](auto& x,auto& ref){return source(x,ref);});if(c.status().ok)take(validate_work_period_value(v));return c.status();}
template<class C> Status craft(C& c,CraftWorkGate& v){c.object("execution_binding",[&](auto& x){return binding(x,v.execution_binding);});c.field("gate_ordinal",v.gate_ordinal);c.object("gate_opened_at",[&](auto& x){return moment(x,v.gate_opened_at);});c.object("last_accounted_at",[&](auto& x){return moment(x,v.last_accounted_at);});c.object("earned_service_units",[&](auto& x){return work_units(x,v.earned_service_units);});Integer pace=static_cast<Integer>(v.pace_for_gate);finite(c,"pace_for_gate",pace,1);if(c.status().ok&&c.reading())v.pace_for_gate=static_cast<CraftPace>(pace);required_ref(c,"accepted_pace_source_ref",v.accepted_pace_source_ref);c.field("rush_units_committed",v.rush_units_committed);optional_ref(c,"last_closed_gate_result_ref",v.last_closed_gate_result_ref);c.optional("pending_stage_ordinal",v.pending_stage_ordinal,[](auto& x,auto& ordinal){x.field("value",ordinal);if(x.status().ok&&ordinal<0)return x.reject("InvalidCraftStageOrdinal");return x.status();});optional_ref(c,"terminal_result_ref",v.terminal_result_ref);if(c.status().ok&&(v.gate_ordinal<0||v.rush_units_committed<0||!std::holds_alternative<ActorActionWorkBinding>(v.execution_binding)))return c.reject("InvalidCraftGate");return c.status();}
template<class C> Status craft_result(C& c,CraftWorkGateResult& v){required_ref(c,"result_id",v.result_id);c.object("execution_binding",[&](auto& x){return binding(x,v.execution_binding);});c.field("gate_ordinal",v.gate_ordinal);references(c,"actual_service_source_refs",v.actual_service_source_refs);c.field("work_units_before",v.work_units_before);c.field("work_units_added",v.work_units_added);c.field("work_units_after",v.work_units_after);c.sequence("reached_stage_ordinals",v.reached_stage_ordinals,[](auto& x,auto& ordinal){return x.field("value",ordinal);});references(c,"material_effect_refs",v.material_effect_refs);references(c,"fee_receipt_refs",v.fee_receipt_refs);references(c,"exertion_source_refs",v.exertion_source_refs);if(c.status().ok&&(v.gate_ordinal<0||v.work_units_before<0||v.work_units_added<=0||v.work_units_after<v.work_units_before||v.work_units_after-v.work_units_before!=v.work_units_added))return c.reject("InvalidCraftGateResult");return c.status();}
template<class C> Status original(C& c,OriginalHalfDayGate& v){c.object("original_execution_binding",[&](auto& x){return binding(x,v.original_execution_binding);});Integer profile=static_cast<Integer>(v.original_gate_profile_ref);finite(c,"original_gate_profile_ref",profile,4);if(c.status().ok&&c.reading())v.original_gate_profile_ref=static_cast<OriginalHalfDayGateProfile>(profile);c.optional("last_consumed_period_ref",v.last_consumed_period_ref,[](auto& x,auto& p){return period(x,p);});c.field("next_period_ordinal",v.next_period_ordinal);if(c.status().ok&&(v.next_period_ordinal<0||!std::holds_alternative<ActorActionWorkBinding>(v.original_execution_binding)))return c.reject("InvalidOriginalHalfDayGate");return c.status();}
template<class C> Status original_result(C& c,OriginalHalfDayGateResult& v){c.object("execution_binding",[&](auto& x){return binding(x,v.execution_binding);});c.object("period_source_ref",[&](auto& x){return period(x,v.period_source_ref);});c.field("gate_ordinal",v.gate_ordinal);c.field("provided_work_units",v.provided_work_units);c.field("completed_before",v.completed_before);c.field("completed_after",v.completed_after);c.field("processed_tick",v.processed_tick);source_list(c,"stage_result_refs",v.stage_result_refs);if(c.status().ok&&(v.gate_ordinal<0||v.provided_work_units<0||v.completed_before<0||v.completed_after<v.completed_before||v.completed_after-v.completed_before!=v.provided_work_units||v.processed_tick!=v.period_source_ref.to_tick||!same_work_binding(v.execution_binding,v.period_source_ref.binding)))return c.reject("InvalidOriginalHalfDayGateResult");return c.status();}
// life具名gate三字段严格保存，执行累计只在同一WorkExecutionState。
template<class C> Status life(C& c,LifeHalfDayStageGateState& v){StableId profile;if(!c.reading()){const auto* name=life_half_day_stage_profile_name(v.gate_profile_ref);if(!name)return c.reject("UnknownLifeHalfDayGateProfile");profile=name;}required_ref(c,"gate_profile_ref",profile);if(c.status().ok&&c.reading()){bool matched=false;for(unsigned i=0;i<7;++i)if(profile==life_half_day_stage_profile_name(static_cast<LifeHalfDayStageGateProfile>(i))){v.gate_profile_ref=static_cast<LifeHalfDayStageGateProfile>(i);matched=true;break;}if(!matched)return c.reject("UnknownLifeHalfDayGateProfile");}c.object("stage_rule_source_ref",[&](auto& x){return source(x,v.stage_rule_source_ref);});return c.object("earned_service_units",[&](auto& x){return work_units(x,v.earned_service_units);});}
template<class C> Status life_period_ref(C& c,LifeWorkPeriodSourceRef& v){c.object("source_ref",[&](auto& x){return source(x,v.source_ref);});return schema(c,"source_schema",v.source_schema);}
template<class C> Status life_result(C& c,LifeHalfDayStageGateResult& v){c.object("work_period_ref",[&](auto& x){return life_period_ref(x,v.work_period_ref);});c.field("completed_halfday_ordinal",v.completed_halfday_ordinal);c.sequence("completed_stage_ordinals",v.completed_stage_ordinals,[](auto& x,auto& ordinal){return x.field("value",ordinal);});source_list(c,"original_stage_result_refs",v.original_stage_result_refs);if(c.status().ok&&v.completed_halfday_ordinal<0)return c.reject("InvalidLifeHalfDayOrdinal");Integer prior=-1;for(auto stage:v.completed_stage_ordinals){if(stage<0||stage<=prior)return c.reject("InvalidLifeStageOrder");prior=stage;}return c.status();}
template<class C> Status shared(C& c,SharedWorkElapsedState& v){state(c,v.execution);Integer tag=v.gate.index();finite(c,"gate_kind",tag,2);if(!c.status().ok)return c.status();if(c.reading()){if(tag==0){if(!prepare_checkpoint_default_values<CraftWorkGate>(c).ok)return c.status();v.gate=CraftWorkGate{};}else if(tag==1){if(!prepare_checkpoint_default_values<OriginalHalfDayGate>(c).ok)return c.status();v.gate=OriginalHalfDayGate{};}else{if(!prepare_checkpoint_default_values<LifeHalfDayStageGateState>(c).ok)return c.status();v.gate=LifeHalfDayStageGateState{};}}return c.object("gate",[&](auto& x){return std::visit([&](auto& gate)->Status{using T=std::decay_t<decltype(gate)>;if constexpr(std::is_same_v<T,CraftWorkGate>)return craft(x,gate);else if constexpr(std::is_same_v<T,OriginalHalfDayGate>)return original(x,gate);else return life(x,gate);},v.gate);});}
template<class C> Status result(C& c,SharedWorkGateResult& v){Integer tag=v.index();finite(c,"gate_kind",tag,2);if(!c.status().ok)return c.status();if(c.reading()){if(tag==0){if(!prepare_checkpoint_default_values<CraftWorkGateResult>(c).ok)return c.status();v=CraftWorkGateResult{};}else if(tag==1){if(!prepare_checkpoint_default_values<OriginalHalfDayGateResult>(c).ok)return c.status();v=OriginalHalfDayGateResult{};}else{if(!prepare_checkpoint_default_values<LifeHalfDayStageGateResult>(c).ok)return c.status();v=LifeHalfDayStageGateResult{};}}return c.object("payload",[&](auto& x){return std::visit([&](auto& result)->Status{using T=std::decay_t<decltype(result)>;if constexpr(std::is_same_v<T,CraftWorkGateResult>)return craft_result(x,result);else if constexpr(std::is_same_v<T,OriginalHalfDayGateResult>)return original_result(x,result);else return life_result(x,result);},v);});}
}
